arguments.command:
cd /workspace/submission && ls -la && python3 -c "
import os,stat
total=0;count=0
for root,dirs,files in os.walk('/workspace/submission'):
    for name in dirs+files:
        p=os.path.join(root,name)
        st=os.lstat(p)
        count+=1
        if stat.S_ISREG(st.st_mode): total+=st.st_size
        else: print('NON REGULAR',p)
        if st.st_nlink!=1: print('HARDLINK',p)
print('entries',count,'bytes',total)
"
